<?php
declare(strict_types=1);
require_once __DIR__ . '/../Config/database.php';
require_once __DIR__ . '/../Config/mikrotik.php';
header('Content-Type: application/json; charset=utf-8');
function out(bool $ok,string $msg='',array $data=[]):never{echo json_encode(array_merge(['success'=>$ok,'message'=>$msg],$data),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
try{$u=trim((string)($_GET['username']??''));$days=max(1,min(90,(int)($_GET['days']??30)));if($u==='')out(false,'Username wajib diisi.');$cfg=new MikroTikConfig();$rid=(int)($_GET['router_id']??0);$router=$rid>0?$cfg->getRouterById($rid):$cfg->getRouter();if(!$router)out(false,'Router tidak ditemukan.');$rid=(int)$router['id'];$pdo=(new Database())->connect();$pdo->exec("CREATE TABLE IF NOT EXISTS hotspot_traffic_user_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,router_id INT NULL,username VARCHAR(100) NOT NULL,session_id VARCHAR(120) NOT NULL DEFAULT '',recorded_at DATETIME NOT NULL,bytes_in BIGINT UNSIGNED NOT NULL DEFAULT 0,bytes_out BIGINT UNSIGNED NOT NULL DEFAULT 0,upload_bps DECIMAL(20,2) NOT NULL DEFAULT 0,download_bps DECIMAL(20,2) NOT NULL DEFAULT 0,address VARCHAR(64) NOT NULL DEFAULT '',interface_name VARCHAR(150) NOT NULL DEFAULT '',KEY idx_hbs(router_id,username,recorded_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$q=$pdo->prepare("SELECT session_id,recorded_at,bytes_in,bytes_out,upload_bps,download_bps FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(NOW(),INTERVAL {$days} DAY) ORDER BY recorded_at ASC,id ASC");$q->execute([$rid,$u]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$prev=[];$download=0;$upload=0;$duration=0;$sessions=[];foreach($rows as $r){$sid=(string)$r['session_id'];if($sid==='')continue;$t=strtotime((string)$r['recorded_at']);if(!isset($sessions[$sid]))$sessions[$sid]=['start'=>$t,'end'=>$t,'down'=>0,'up'=>0];$sessions[$sid]['end']=$t;if(isset($prev[$sid])){$di=(int)$r['bytes_in']-$prev[$sid][0];$do=(int)$r['bytes_out']-$prev[$sid][1];if($di>=0){$upload+=$di;$sessions[$sid]['up']+=$di;}if($do>=0){$download+=$do;$sessions[$sid]['down']+=$do;}}$prev[$sid]=[(int)$r['bytes_in'],(int)$r['bytes_out']];}$longest=0;foreach($sessions as $s){$x=max(0,$s['end']-$s['start']);$duration+=$x;$longest=max($longest,$x);}out(true,'',['router_id'=>$rid,'router_name'=>(string)$router['name'],'username'=>$u,'period_days'=>$days,'summary'=>['sessions'=>count($sessions),'traffic_bytes'=>(string)($download+$upload),'download_bytes'=>(string)$download,'upload_bytes'=>(string)$upload,'total_duration_seconds'=>$duration,'average_duration_seconds'=>count($sessions)?round($duration/count($sessions)):0,'longest_session_seconds'=>$longest,'records'=>count($rows)]]);}catch(Throwable $e){out(false,$e->getMessage());}